@OutputTypeDefinition_e4878d8c NVARCHAR(MAX),
@OutputTypeIsArray_e4878d8c BIT,
@ExecutionMode_e4878d8c NVARCHAR(20),
@RequiredScope_e4878d8c NVARCHAR(255),
@RequiresSystemUser_e4878d8c BIT,
@GenerationType_e4878d8c NVARCHAR(20),
@Code_e4878d8c NVARCHAR(MAX),
@CodeApprovalStatus_e4878d8c NVARCHAR(20),
@CodeApprovedByUserID_e4878d8c UNIQUEIDENTIFIER,
