DECLARE @ID_85f6bd5e UNIQUEIDENTIFIER,
@Name_85f6bd5e NVARCHAR(255),
@CategoryID_85f6bd5e UNIQUEIDENTIFIER,
@UserQuestion_85f6bd5e NVARCHAR(MAX),
@Description_85f6bd5e NVARCHAR(MAX),
@SQL_85f6bd5e NVARCHAR(MAX),
@TechnicalDescription_85f6bd5e NVARCHAR(MAX),
@OriginalSQL_85f6bd5e NVARCHAR(MAX),
@Feedback_85f6bd5e NVARCHAR(MAX),
@Status_85f6bd5e NVARCHAR(15),
@QualityRank_85f6bd5e INT,
@ExecutionCostRank_85f6bd5e INT,
@UsesTemplate_85f6bd5e BIT,
@AuditQueryRuns_85f6bd5e BIT,
@CacheEnabled_85f6bd5e BIT,
@CacheTTLMinutes_85f6bd5e INT,
@CacheMaxSize_85f6bd5e INT,
@EmbeddingVector_85f6bd5e NVARCHAR(MAX),
@EmbeddingModelID_85f6bd5e UNIQUEIDENTIFIER,
@CacheValidationSQL_85f6bd5e NVARCHAR(MAX),
@SQLDialectID_85f6bd5e UNIQUEIDENTIFIER,
@Reusable_85f6bd5e BIT,
@ExternalDataSourceID_85f6bd5e UNIQUEIDENTIFIER,
@IsMaterialized_85f6bd5e BIT
SET
  @ID_85f6bd5e = '8FCC8439-03ED-4426-A289-C9B8973D6560'
SET
  @Name_85f6bd5e = N'Party Order Lifetime'
SET
  @CategoryID_85f6bd5e = 'D6586F51-1F67-4F50-BA28-7DB8A98BD4D2'
SET
  @UserQuestion_85f6bd5e = N'What is this person or organization''s order lifetime — counts, LTV, and years as a customer?'
SET
  @Description_85f6bd5e = N'Single-row party header stats: non-voided order count, open/overdue counts, lifetime gross, first order date, years as customer, and active subscription count. Used by the Person and Organization form headers so those figures are one indexed aggregate instead of four count RunViews plus extra money queries.'
SET
  @SQL_85f6bd5e = N'-- One-row party lifetime for the Person / Organization form header.
-- PartyKind is only used in Nunjucks branches — it never touches SQL text.
-- PartyID is quoted via sqlString.
SELECT
    ISNULL(o.OrderCount, 0) AS OrderCount,
    ISNULL(o.OpenCount, 0) AS OpenCount,
    ISNULL(o.OverdueCount, 0) AS OverdueCount,
    ISNULL(o.LifetimeValue, 0) AS LifetimeValue,
    o.FirstOrderDate,
    CASE
        WHEN o.FirstOrderDate IS NULL THEN NULL
        ELSE DATEDIFF(year, o.FirstOrderDate, SYSUTCDATETIME())
    END AS YearsAsCustomer,
    ISNULL(s.ActiveSubCount, 0) AS ActiveSubCount
FROM (SELECT 1 AS OneRow) AS seed
OUTER APPLY (
    SELECT
        COUNT(*) AS OrderCount,
        SUM(CASE WHEN ISNULL(h.IsOverdue, 0) = 1 OR ISNULL(h.Balance, 0) > 0 THEN 1 ELSE 0 END) AS OpenCount,
        SUM(CASE WHEN ISNULL(h.IsOverdue, 0) = 1 THEN 1 ELSE 0 END) AS OverdueCount,
        SUM(ISNULL(h.TotalGross, 0)) AS LifetimeValue,
        MIN(h.OrderDate) AS FirstOrderDate
    FROM [${flyway:defaultSchema}].vwOrderHeaders h
    WHERE h.Status <> N''Voided''
      {% if PartyKind == "person" %}
      AND h.BillToPersonID = {{ PartyID | sqlString }}
      {% else %}
      AND h.BillToOrganizationID = {{ PartyID | sqlString }}
      {% endif %}
) o
OUTER APPLY (
    SELECT COUNT(*) AS ActiveSubCount
    FROM [${flyway:defaultSchema}].vwSubscriptions sub
    WHERE sub.Status = N''Active''
      {% if PartyKind == "person" %}
      AND sub.BeneficiaryPersonID = {{ PartyID | sqlString }}
      {% else %}
      AND sub.HolderOrganizationID = {{ PartyID | sqlString }}
      {% endif %}
) s;
'
SET
  @TechnicalDescription_85f6bd5e = N'Nunjucks-parameterized. PartyKind (person|organization) selects the bill-to / subscription join column; PartyID is the party UUID and is always passed through the sqlString filter. Aggregates __mj_BizAppsOrders.vwOrderHeaders (Status <> Voided) and vwSubscriptions (Status = Active). Returns one row even when the party has no orders.'
SET
  @Status_85f6bd5e = N'Approved'
SET
  @QualityRank_85f6bd5e = 8
SET
  @ExecutionCostRank_85f6bd5e = 2
SET
  @UsesTemplate_85f6bd5e = 1
SET
  @AuditQueryRuns_85f6bd5e = 0
SET
