-- Save MJ: Template Params (core SP call only)
DECLARE @ID_d12e4654 UNIQUEIDENTIFIER,
@TemplateID_d12e4654 UNIQUEIDENTIFIER,
@Name_d12e4654 NVARCHAR(255),
@Description_d12e4654 NVARCHAR(MAX),
@Type_d12e4654 NVARCHAR(20),
@DefaultValue_d12e4654 NVARCHAR(MAX),
@IsRequired_d12e4654 BIT,
@LinkedParameterName_d12e4654 NVARCHAR(255),
@LinkedParameterField_d12e4654 NVARCHAR(500),
@ExtraFilter_d12e4654 NVARCHAR(MAX),
@EntityID_d12e4654 UNIQUEIDENTIFIER,
